  gap: var(--space-4);
}

.special-store {
  background: var(--color-bg-white);
  border-radius: 18px;
  padding: var(--space-8);
}

.special-store .store-title {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.special-store .store-desc {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
}

/* === Product Experience === */
.product-experience {
  background: var(--color-bg-white);
  border-radius: 18px;
  padding: var(--space-12);
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.product-experience .exp-content {
  flex: 1;
}

.product-experience .exp-title {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  margin-bottom: var(--space-4);
}

.product-experience .exp-desc {
  font-size: var(--font-size-lg);
  color: var(--color-secondary);
  margin-bottom: var(--space-6);
}

.product-experience .exp-image {
  flex: 1;
}

/* === Setup Support === */
.setup-support {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.setup-card {
  background: var(--color-bg-white);
  border-radius: 18px;
  padding: var(--space-8);
  display: flex;
  gap: var(--space-6);
}

.setup-card .setup-icon {
  width: 56px;
  height: 56px;
  background: var(--color-bg);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.setup-card .setup-title {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.setup-card .setup-desc {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
}

/* === Responsive === */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
