  font-weight: 500;
  color: var(--color-link);
  padding: var(--space-3) var(--space-6);
  border: 1px solid var(--color-link);
  border-radius: 980px;
  transition: all var(--transition-fast);
}

.quick-link:hover {
  background: var(--color-link);
  color: white;
  text-decoration: none;
}

/* === Footer === */
.footer {
  background: var(--color-bg);
  border-top: 1px solid var(--color-border);
  padding: var(--space-12) 0 var(--space-8);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.footer-promo {
  text-align: center;
  padding-bottom: var(--space-8);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--space-8);
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-8);
  margin-bottom: var(--space-8);
}

.footer-section h3 {
  font-size: var(--font-size-sm);
  font-weight: 600;
  margin-bottom: var(--space-4);
  color: var(--color-primary);
}

.footer-section ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.footer-section a {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
}

.footer-section a:hover {
  color: var(--color-primary);
}

.footer-legal {
  text-align: center;
  font-size: var(--font-size-xs);
  color: var(--color-secondary);
  padding-top: var(--space-8);
  border-top: 1px solid var(--color-border);
}

/* Footer Accordion (Mobile) */
.footer-section .mobile-toggle {
  display: none;
  width: 100%;
  text-align: left;
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--color-primary);
  padding: var(--space-3) 0;
  cursor: pointer;
}

.footer-section .mobile-toggle::after {
  content: '+';
  float: right;
  font-size: var(--font-size-lg);
}

.footer-section.expanded .mobile-toggle::after {
  content: '−';
}

.footer-section .mobile-toggle:hover {
  color: var(--color-secondary);
}

/* === Hero Sections === */
.hero-section {
  background: var(--color-bg-white);
  padding: var(--space-16) 0;
  text-align: center;
}

.hero-title {
  font-size: var(--font-size-5xl);
  font-weight: 700;
  margin-bottom: var(--space-4);
}

.hero-subtitle {
  font-size: var(--font-size-xl);
  color: var(--color-secondary);
  margin-bottom: var(--space-8);
}

.hero-actions {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  flex-wrap: wrap;
}

.hero-actions .btn {
  padding: var(--space-3) var(--space-8);
  border-radius: 980px;
  font-size: var(--font-size-base);
  font-weight: 500;
}

.hero-actions .btn-primary {
  background: var(--color-link);
  color: white;
}

.hero-actions .btn-secondary {
  background: transparent;
  color: var(--color-link);
  border: 1px solid var(--color-link);
}

/* === Category Hero === */
.category-hero {
  background: var(--color-bg-white);
  padding: var(--space-16) 0;
  text-align: center;
}

.category-hero .category-icon {
  width: 80px;
  height: 80px;
  background: var(--color-bg);
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-6);
}

.category-hero .hero-title {
  font-size: var(--font-size-4xl);
}

/* === Guide Cards === */
.guide-cards {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-4);
}

.guide-card {
  background: var(--color-bg-white);
  border-radius: 18px;
  padding: var(--space-6);
}

.guide-card .guide-icon {
  width: 48px;
  height: 48px;
  background: var(--color-bg);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-4);
}

.guide-card .guide-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.guide-card .guide-desc {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
}

/* === Way Cards === */
.way-cards {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-4);
}

.way-card {
  background: var(--color-bg-white);
  border-radius: 18px;
  padding: var(--space-6);
}

.way-card .way-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.way-card .way-desc {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
}

/* === Special Stores === */
.special-stores {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.special-store {
  background: var(--color-bg-white);
  border-radius: 18px;
  padding: var(--space-8);
}

.special-store .store-title {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.special-store .store-desc {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
}

/* === Product Experience === */
.product-experience {
  background: var(--color-bg-white);
  border-radius: 18px;
  padding: var(--space-12);
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.product-experience .exp-content {
  flex: 1;
}

.product-experience .exp-title {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  margin-bottom: var(--space-4);
}

.product-experience .exp-desc {
  font-size: var(--font-size-lg);
  color: var(--color-secondary);
  margin-bottom: var(--space-6);
}

.product-experience .exp-image {
  flex: 1;
}

/* === Setup Support === */
.setup-support {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.setup-card {
  background: var(--color-bg-white);
  border-radius: 18px;
  padding: var(--space-8);
  display: flex;
  gap: var(--space-6);
}

.setup-card .setup-icon {
  width: 56px;
  height: 56px;
  background: var(--color-bg);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.setup-card .setup-title {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.setup-card .setup-desc {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
}

/* === Responsive === */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .guide-cards,
  .way-cards {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --font-size-5xl: 2.5rem;
    --font-size-4xl: 2rem;
    --font-size-3xl: 1.5rem;
  }

  .nav-links {
    display: none;
  }

  .product-grid {
    grid-template-columns: 1fr;
  }

  .category-bar {
    gap: var(--space-4);
    justify-content: flex-start;
  }

  .guide-cards,
  .way-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .special-stores {
    grid-template-columns: 1fr;
  }

  .product-experience {
    flex-direction: column;
  }

  .setup-support {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
